import {escapeHtml as esc} from './components.js';
import {eventLabels,changeLabels,holdingEventSummary} from './research-model.js';
import {economicMetrics,usd} from './calendar-presentation.js';
export const number=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:4}):'확인 불가';
export const pct=n=>Number.isFinite(n)?(n>0?'+':n<0?'−':'')+Math.abs(n).toFixed(2)+'%':'확인 불가';
export const updated=at=>/^\d{4}-\d{2}-\d{2}$/.test(at||'')?at+' · 일자 기준':at&&Number.isFinite(Date.parse(at))?new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'시각 미제공';
export const safeLink=url=>{try{const u=new URL(url,location.origin);return ['https:','http:'].includes(u.protocol)&&(!u.origin.includes('127.0.0.1')||u.origin===location.origin)?esc(url):'#';}catch{return '#';}};
export function eventMarkup(e,{stock=false,readControl=false,compactReports=false,report=null}={}){
 const date=e.at?updated(e.at)+(e.precision==='posted'?' 게시':''):e.date+' · '+(e.precision==='session'?(e.session||'발표 시점 미정')+' / KST 날짜':'일자 기준');
 const destination=e.reportId?`<button data-research-report="${esc(e.reportId)}">${esc(e.title)}</button>`:e.chartDate?`<button data-research-date="${e.chartDate}">${esc(e.title)}</button>`:`<a data-nav href="${safeLink(e.href||'/stock/'+e.key.replace(':','/'))}">${esc(e.title)}</a>`;
 if(compactReports&&e.kind==='report'){
  const analyst=report?.analyst,target=analyst?.target||report?.target||e.target;
  const revision=analyst?(analyst.targetRevision||analyst.targetRevisionExplicit):report?.revision||report?.explicitRevision||e.revision;
  const direction={up:'상향',down:'하향',unchanged:'유지',new:'신규 제시'}[revision]||'변경 미확인';
  const amount=Number.isFinite(target?.value)?number(target.value)+' '+(target.currency==='KRW'?'원':target.currency||'통화 미확인'):'미기재';
  const issued=report?.date||e.publishedDate||e.originalDate||'미확인';
  return `<article class="research-event research-report-compact"><div class="research-event-main">${destination}<div class="research-report-facts"><span>목표주가 <strong>${esc(amount)}</strong></span><b class="report-target-${esc(revision||'none')}">${esc(direction)}</b><span>${esc(report?.broker||e.source||'증권사 미확인')}</span><span>발행일 ${esc(issued)}</span></div></div></article>`;
 }
 const details=[e.context,e.kind!=='manager'&&e.period?'보유 기준 '+e.period:null,e.kind!=='manager'&&e.changeType?changeLabels[e.changeType]:null,e.revision==='up'?'목표주가 상향':e.revision==='down'?'목표주가 하향':null,e.detail,Number.isFinite(e.epsActual)?'조정 EPS 실제 '+usd(e.epsActual):null,Number.isFinite(e.epsEstimate)?'EPS 예상 '+usd(e.epsEstimate):null,Number.isFinite(e.revenueActual)?'매출 실제 '+usd(e.revenueActual,true):null,Number.isFinite(e.revenueEstimate)?'매출 예상 '+usd(e.revenueEstimate,true):null,...(e.kind==='calendar'?economicMetrics(e).map(([label,value])=>label+' '+value):[])].filter(Boolean);
 const state={scheduled:'예정',released:'발표 완료',awaiting_result:'발표값 대기',observed:'관측된 주가 변화',published:e.kind==='manager'?'공시':'발행'}[e.state]||(e.kind==='price'?'관측된 주가 변화':'');
 const eventId=e.eventId||'',basis=e.dataPeriod||e.dataDate||(e.kind==='report'?e.date:null);
 return `<article class="research-event" ${eventId?`data-event-id="${esc(eventId)}"`:''}><span class="research-tag ${e.kind}">${eventLabels[e.kind]}</span><div class="research-event-main">${stock?`<a data-nav class="research-stock-link" href="/stock/${esc(e.key.replace(':','/'))}">${esc(e.key)}</a>`:''}${state?`<span class="event-state ${esc(e.state||'observed')}">${state}</span>`:''}${destination}${e.kind==='manager'?`<p class="research-filing-summary">${esc(holdingEventSummary(e))}</p>`:''}<small>${esc(date)} · ${esc(e.source||'출처 미제공')}</small>${basis?`<small>자료 기준 ${esc(basis)}</small>`:''}${details.length?`<p>${esc(details.join(' · '))}</p>`:''}<details class="research-evidence"><summary>출처·기준 시각</summary><span>발표 ${esc(e.publishedAt?updated(e.publishedAt):e.publishedDate?e.publishedDate+' · 일자 기준':'시각 미제공')}${e.scheduledAt?' · 예정 '+esc(updated(e.scheduledAt)):''}</span>${e.sourcePostedAt?`<span>원본 게시 ${esc(updated(e.sourcePostedAt))}</span>`:''}<span>${e.originalDate?esc('원본 '+e.originalDate+(e.originalTime?' '+e.originalTime:'')+' · '+(e.originalTimeZone||e.timeZone||'날짜 기준')):''}</span><span>수집 ${esc(updated(e.schemaVersion?e.collectedAt:e.collectedAt||e.updatedAt))}</span>${e.sourceModifiedAt?`<span>원본 수정 ${esc(updated(e.sourceModifiedAt))}</span>`:''}${(e.sources||[]).map(s=>s.url?`<a href="${safeLink(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`:`<span>${esc(s.name)}</span>`).join('')}</details>${e.eventRevision>1?`<button class="event-history-button" data-event-history="${eventId}" data-event-key="${esc(e.key)}" aria-expanded="false">변경 이력 ${e.eventRevision}개</button><div class="event-history" hidden></div>`:''}${readControl&&eventId?`<button class="event-read-button" data-event-read="${eventId}" data-event-revision="${e.eventRevision}" ${e.unread?'':'disabled'}>${e.unread?'읽음 처리':'읽음'}</button>`:''}</div></article>`;
}
export function coverageMarkup(coverage){return Object.entries(coverage||{}).filter(([,v])=>['error','unavailable','stale'].includes(v.status)||v.unmatched>0).map(([key,v])=>`<span>${esc({reports:'리포트',managers:'운용사',earnings:'실적',calendar:'일정'}[key]||key)} · ${esc(v.message||'마지막 조회 자료')}</span>`).join('');}
export async function fetchResearch(symbols,signal,options={}){const response=await fetch('/api/research?'+new URLSearchParams({symbols:symbols.join(','),stored:'1',...options}),{signal:AbortSignal.any([signal,AbortSignal.timeout(60000)])});if(!response.ok)throw new Error('최근 변화 데이터를 불러오지 못했습니다.');return response.json();}
export async function markResearchRead(items,signal){for(let i=0;i<items.length;i+=20){const response=await fetch('/api/research/read',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:items.slice(i,i+20).map(e=>({id:e.eventId,revision:e.eventRevision}))}),signal});if(!response.ok)throw new Error('읽음 상태 저장 실패');}dispatchEvent(new CustomEvent('moa-research-read',{detail:items.map(e=>({id:e.eventId,revision:e.eventRevision}))}));}
export async function showEventHistory(event,signal){const b=event.target.closest('[data-event-history]');if(!b)return;const box=b.nextElementSibling;box.hidden=!box.hidden;b.setAttribute('aria-expanded',String(!box.hidden));if(box.hidden||box.dataset.loaded)return;box.textContent='변경 이력을 확인하고 있어요';try{const data=await fetchResearch([b.dataset.eventKey],signal,{history:b.dataset.eventHistory});box.innerHTML=data.items.map(v=>`<div><strong>버전 ${v.eventRevision} · ${esc(v.title)}</strong><p>${esc(v.kind==='manager'?holdingEventSummary(v):[v.target?'목표주가 '+number(v.target.value)+' '+v.target.currency:null,v.rating,Number.isFinite(v.epsActual)?'EPS 실제 '+number(v.epsActual):null,Number.isFinite(v.epsEstimate)?'EPS 예상 '+number(v.epsEstimate):null,v.actual?'발표치 '+v.actual:null,v.expected?'예상 '+v.expected:null,v.close?'일봉 종가 '+number(v.close):null].filter(Boolean).join(' · ')||'원본 정보 변경')}</p><small>발표 ${esc(v.publishedDate||updated(v.publishedAt))} · 자료 기준 ${esc(v.dataDate||v.dataPeriod||'미제공')}</small><small>수집 ${esc(updated(v.collectedAt))} · 기록 ${esc(updated(v.recordedAt))}</small></div>`).join('');box.dataset.loaded='true';}catch{box.textContent='변경 이력을 불러오지 못했습니다.';}}
